using System.Globalization;

namespace Hasseware.AspNetCore.Components.Bpmn.Editing;

/// <summary>
/// Mints XML-safe element ids.
/// </summary>
/// <remarks>
/// Ids are generated by the caller rather than inside a command, so applying a command stays pure:
/// the same command produces the same document every time, and a test can name the element it
/// expects instead of discovering it. Section 9.3 requires the id to be fresh, globally unique and
/// XML-safe, which is all this does.
/// </remarks>
public static class BpmnId
{
    /// <summary>
    /// A new id of the form <c>Prefix_0a1b…</c>.
    /// </summary>
    /// <remarks>
    /// The prefix is what makes a document readable in a diff and in a validation report, and it
    /// is what every BPMN tool does. An <c>xsd:ID</c> may not start with a digit, which a bare GUID
    /// can, so the prefix is load-bearing rather than cosmetic.
    /// </remarks>
    /// <param name="prefix">A readable prefix, for example <c>Task</c> or <c>Flow</c>.</param>
    /// <returns>An id unique within any practical document.</returns>
    public static string New(string prefix)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(prefix);

        return string.Create(CultureInfo.InvariantCulture, $"{Sanitize(prefix)}_{Guid.NewGuid():N}");
    }

    /// <summary>The DI id conventionally paired with an element id.</summary>
    /// <param name="elementId">The semantic element's id.</param>
    /// <returns>The element id with the <c>_di</c> suffix every exporter uses.</returns>
    public static string ForDiagramElement(string elementId)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(elementId);

        return $"{elementId}_di";
    }

    /// <summary>
    /// Strips anything an <c>xsd:ID</c> may not contain, and anything that may not start one.
    /// </summary>
    /// <remarks>
    /// Callers pass literals today, so this never fires — but an id built from a user-supplied
    /// label is an obvious next step, and a document with an unparseable id is not recoverable by
    /// the reader.
    /// </remarks>
    private static string Sanitize(string prefix)
    {
        var safe = new string([.. prefix.Where(character => char.IsLetterOrDigit(character) || character is '_' or '-')]);

        return safe.Length == 0 || !char.IsLetter(safe[0]) ? $"id{safe}" : safe;
    }
}
